const icons = {
 ring:'<circle cx="12" cy="14" r="8"/><path d="m8 3 2-2h4l2 2-4 3z"/>',
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 calendar:'<rect x="3" y="5" width="18" height="17" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',
 palette:'<path d="M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 1.4-3.4c-.8-.8-.2-2.1.9-2.1H17a4 4 0 0 0 4-4C21 6.8 17 3 12 3Z"/><circle cx="7.5" cy="10" r=".6"/><circle cx="10.5" cy="6.5" r=".6"/><circle cx="15" cy="7" r=".6"/><circle cx="17.5" cy="11" r=".6"/>',
 location:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',
 tag:'<path d="M20 3H11L2 12l10 10 9-9V4a1 1 0 0 0-1-1Z"/><circle cx="16.5" cy="7.5" r="1"/>',
 users:'<circle cx="9" cy="7" r="4"/><path d="M1 21v-2a8 8 0 0 1 16 0v2ZM16 4a4 4 0 0 1 0 8m3 3a6 6 0 0 1 4 6"/>',
 user:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="9" r="3"/><path d="M5 18a7 7 0 0 1 14 0"/>',
 arrow:'<path d="M3 12h17m-6-6 6 6-6 6"/>',
 verified:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m8.5 12 2.2 2.2 4.8-5"/>',
 heart:'<path d="M20.8 4.7a5.5 5.5 0 0 0-7.8 0L12 5.8l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.5a5.5 5.5 0 0 0 0-7.8Z"/>',
 budget:'<circle cx="12" cy="12" r="9"/><path d="M12 3v9h9M8.5 16.5l3.5-4.5"/>',
 bookmark:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el => el.innerHTML=icon(el.dataset.icon));
const categories=['Venues','Photographers','Florists','Caterers','Cakes & Desserts','Hair & Makeup','Entertainment','Styling & Hire','Videographers','Celebrants','Wedding Planners','Transport','Stationery','Bridal Wear','Suits & Menswear','Jewellery','Accommodation','Photo Booths','Invitations','Wedding Hire'];
const overallBudgets=['Under $20,000','$20,000–$35,000','$35,000–$50,000','$50,000–$75,000','$75,000–$100,000','$100,000+','Not sure yet'];
const locationOptions=['Anywhere','Australia','New South Wales, Australia','Victoria, Australia','Queensland, Australia','South Australia, Australia','Western Australia, Australia','Tasmania, Australia','Australian Capital Territory, Australia','Northern Territory, Australia','Sydney, New South Wales, Australia','Melbourne, Victoria, Australia','Brisbane, Queensland, Australia','Perth, Western Australia, Australia','Adelaide, South Australia, Australia','Hobart, Tasmania, Australia','Canberra, Australian Capital Territory, Australia','Darwin, Northern Territory, Australia','Hunter Valley, New South Wales, Australia','Byron Bay, New South Wales, Australia','Blue Mountains, New South Wales, Australia','Southern Highlands, New South Wales, Australia','Gold Coast, Queensland, Australia','Sunshine Coast, Queensland, Australia','Yarra Valley, Victoria, Australia','Mornington Peninsula, Victoria, Australia','Margaret River, Western Australia, Australia','New Zealand','Auckland, New Zealand','Queenstown, New Zealand','Italy','Tuscany, Italy','Bali, Indonesia','United Kingdom','United States'];
const state={build:{mode:'undecided',start:'',end:'',suppliers:[]},browse:{mode:'undecided',start:'',end:'',category:''},available:{mode:'exact',start:'',end:'',category:''}};
const options=(values,placeholder)=>`<option value="">${placeholder}</option>${values.map(v=>`<option>${v}</option>`).join('')}`;
function locationField(key,optional=false){const label=key==='browse'?'Location':'Wedding Location';return `<div class="field location-field" data-location-field="${key}"><label class="field-shell" for="${key}-location">${icon('location')}<span class="field-text"><span class="field-label">${label}</span><input id="${key}-location" name="location" aria-label="${label}" aria-expanded="false" aria-controls="${key}-location-popup" role="combobox" autocomplete="off" placeholder="${key==='build'?'e.g. Sydney, Hunter Valley':'Country, state or city'}" ${optional?'':'required'}></span><span class="chevron" aria-hidden="true"></span></label><div class="popover option-popover location-popover" id="${key}-location-popup" data-trigger="${key}-location" role="listbox" aria-label="${label} suggestions" hidden></div></div>`;}
function selectField(id,label,placeholder,values,symbol='tag',required=false){return `<div class="field custom-select" data-custom-select="${id}"><input type="hidden" id="${id}" name="${id}" ${required?'required':''}><button type="button" class="field-shell" id="${id}-trigger" aria-expanded="false" aria-controls="${id}-popup">${icon(symbol)}<span class="field-text"><span class="field-label" id="${id}-label">${label}</span><span class="field-value" id="${id}-value">${placeholder}</span></span><span class="chevron" aria-hidden="true"></span></button><div class="popover option-popover" id="${id}-popup" role="listbox" aria-labelledby="${id}-label" hidden></div></div>`;}
function popupField(key,type,label,placeholder,symbol){return `<div class="field"><button type="button" class="field-shell" id="${key}-${type}-trigger" aria-expanded="false" aria-controls="${key}-${type}-popup">${icon(symbol)}<span class="field-text"><span class="field-label">${label}</span><span class="field-value" id="${key}-${type}-value">${placeholder}</span></span><span class="chevron" aria-hidden="true"></span></button><div class="popover" id="${key}-${type}-popup" role="dialog" aria-label="${label}" hidden></div></div>`;}
function submit(label){return `<button class="search-submit" type="submit">${label} ${icon('arrow')}</button>`;}
document.querySelector('#panel-build').innerHTML=`<form data-search="build" action="https://www.google.com/" novalidate><div class="fields">${locationField('build')}${popupField('build','date','Wedding Date','Select your date','calendar')}<button type="button" class="mobile-more-toggle" aria-expanded="false"><span class="mobile-plus" aria-hidden="true">+</span><span>Add budget &amp; suppliers</span><span class="chevron" aria-hidden="true"></span></button>${selectField('build-budget','Overall Budget','Any budget',overallBudgets,'tag',true)}${popupField('build','suppliers','Suppliers Needed','Select suppliers','users')}${submit('Find My Spark')}</div><p class="validation-error" role="alert" hidden></p></form>`;
document.querySelector('#panel-available').innerHTML=`<form data-search="available" action="https://www.google.com/" novalidate><div class="fields">${popupField('available','date','Wedding Date','Select exact date or date range','calendar')}${selectField('available-category','Supplier Category','Select a category',categories,'tag',true)}${locationField('available')}${selectField('available-budget','Supplier Budget','Budget for this supplier',[])}${submit('See Available Suppliers')}</div><p class="validation-error" role="alert" hidden></p></form>`;
const cropPositions=[137,330,524,718,911,1105,1298,1492].map(x=>`${x/(2002-181)*100}%`);
document.querySelector('#panel-browse').innerHTML=`<form data-search="browse" action="https://www.google.com/" novalidate><h3 class="browse-title">What are you looking for?</h3><div class="category-tiles" aria-label="Supplier categories">${categories.slice(0,8).map((c,i)=>`<button type="button" class="category-tile" data-category="${c}" aria-pressed="false" style="--crop-x:${cropPositions[i]}"><span class="sr-only">${c}</span></button>`).join('')}<button type="button" class="category-tile category-more" id="more-categories" aria-haspopup="dialog" aria-expanded="false" aria-controls="category-options">${icon('grid')}<span>More<br>Categories</span></button></div><div class="category-modal" id="category-options" role="dialog" aria-modal="true" aria-labelledby="category-modal-title" hidden><div class="category-modal-card"><div class="category-modal-heading"><h3 id="category-modal-title">All supplier categories</h3><button type="button" class="category-modal-close" aria-label="Close categories">×</button></div><div class="more-categories">${categories.map(c=>`<button type="button" data-category="${c}" aria-pressed="false">${c}</button>`).join('')}</div></div></div><div class="fields browse-fields">${locationField('browse',true)}${popupField('browse','date','Wedding date (optional)','Exact date, range or not decided','calendar')}${selectField('browse-budget','Budget (optional)','Select a supplier budget',[])}${submit('Browse Suppliers')}</div><p class="validation-error" role="alert" hidden></p></form>`;
function supplierBudget(category){if(['Venues','Caterers'].includes(category))return ['Under $5,000','$5,000–$10,000','$10,000–$20,000','$20,000–$30,000','$30,000+'];if(['Photographers','Videographers','Wedding Planners'].includes(category))return ['Under $2,000','$2,000–$4,000','$4,000–$6,000','$6,000–$10,000','$10,000+'];if(['Hair & Makeup','Cakes & Desserts','Celebrants','Stationery','Invitations'].includes(category))return ['Under $500','$500–$1,000','$1,000–$2,000','$2,000–$3,000','$3,000+'];return ['Under $1,000','$1,000–$3,000','$3,000–$5,000','$5,000–$10,000','$10,000+'];}
function setCustomSelectOptions(id,values,placeholder){const field=document.querySelector(`[data-custom-select="${id}"]`);if(!field)return;const input=document.getElementById(id);if(!values.includes(input.value))input.value='';document.getElementById(`${id}-value`).textContent=input.value||placeholder;const popup=document.getElementById(`${id}-popup`);popup.innerHTML=values.map(value=>`<button type="button" class="option-choice" role="option" aria-selected="${input.value===value}" data-value="${value}">${value}</button>`).join('');popup.querySelectorAll('.option-choice').forEach(button=>button.addEventListener('click',()=>{input.value=button.dataset.value;document.getElementById(`${id}-value`).textContent=button.dataset.value;popup.querySelectorAll('.option-choice').forEach(option=>option.setAttribute('aria-selected',String(option===button)));closePopups();document.getElementById(`${id}-trigger`).focus();input.dispatchEvent(new Event('change',{bubbles:true}));}));}
function wireCustomSelect(id,values,placeholder){setCustomSelectOptions(id,values,placeholder);document.getElementById(`${id}-trigger`).addEventListener('click',()=>togglePopover(id));}
wireCustomSelect('build-budget',overallBudgets,'Any budget');wireCustomSelect('available-category',categories,'Select a category');wireCustomSelect('available-budget',[],'Budget for this supplier');wireCustomSelect('browse-budget',[],'Select a supplier budget');
function updateBudget(key){const category=state[key].category;setCustomSelectOptions(`${key}-budget`,[...supplierBudget(category),'Not sure yet'],'Any budget');const labels={'Venues':'Venue','Photographers':'Photography','Florists':'Florist','Caterers':'Catering','Cakes & Desserts':'Cake','Videographers':'Videography'};document.getElementById(`${key}-budget-label`).textContent=category?`${labels[category]||category} Budget${key==='browse'?' (optional)':''}`:`${key==='browse'?'Budget (optional)':'Supplier Budget'}`;}
updateBudget('browse');updateBudget('available');
document.querySelector('#available-category').addEventListener('change',e=>{state.available.category=e.target.value;updateBudget('available');});
const categoryModal=document.querySelector('#category-options');
const moreCategoriesButton=document.querySelector('#more-categories');
function closeCategoryModal(returnFocus=true){categoryModal.hidden=true;moreCategoriesButton.setAttribute('aria-expanded','false');if(returnFocus)moreCategoriesButton.focus();}
document.querySelectorAll('[data-category]').forEach(button=>button.addEventListener('click',()=>{state.browse.category=button.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===button.dataset.category)));updateBudget('browse');clearError('browse');if(button.closest('.category-modal'))closeCategoryModal();}));
moreCategoriesButton.addEventListener('click',()=>{closePopups();categoryModal.hidden=false;moreCategoriesButton.setAttribute('aria-expanded','true');categoryModal.querySelector('.category-modal-close').focus();});
categoryModal.querySelector('.category-modal-close').addEventListener('click',()=>closeCategoryModal());
categoryModal.addEventListener('click',event=>{if(event.target===categoryModal)closeCategoryModal();});
function closePopups(){document.querySelectorAll('.popover').forEach(p=>{p.hidden=true;const trigger=document.getElementById(p.dataset.trigger||p.id.replace('-popup','-trigger'));trigger?.setAttribute('aria-expanded','false');trigger?.closest('.field-shell')?.classList.remove('is-open');});}
function togglePopover(id){const popup=document.getElementById(`${id}-popup`);const open=popup.hidden;closePopups();if(open){popup.hidden=false;const trigger=document.getElementById(`${id}-trigger`);trigger.setAttribute('aria-expanded','true');popup.querySelector('input,button')?.focus();}}
function togglePopup(key,type){togglePopover(`${key}-${type}`);}
function renderLocationOptions(key,query=''){const popup=document.getElementById(`${key}-location-popup`);const matches=locationOptions.filter(value=>value.toLowerCase().includes(query.trim().toLowerCase())).slice(0,12);popup.innerHTML=matches.length?matches.map(value=>`<button type="button" class="option-choice" role="option" data-value="${value}">${value}</button>`).join(''):'<p class="no-options">No matching locations</p>';popup.querySelectorAll('.option-choice').forEach(button=>button.addEventListener('mousedown',event=>{event.preventDefault();const input=document.getElementById(`${key}-location`);input.value=button.dataset.value;closePopups();input.focus();input.dispatchEvent(new Event('change',{bubbles:true}));}));}
function openLocation(key){const input=document.getElementById(`${key}-location`);const popup=document.getElementById(`${key}-location-popup`);closePopups();renderLocationOptions(key,input.value);popup.hidden=false;input.setAttribute('aria-expanded','true');input.closest('.field-shell').classList.add('is-open');}
function wireLocation(key){const input=document.getElementById(`${key}-location`);input.addEventListener('focus',()=>openLocation(key));input.addEventListener('click',()=>openLocation(key));input.addEventListener('input',()=>{renderLocationOptions(key,input.value);document.getElementById(`${key}-location-popup`).hidden=false;input.setAttribute('aria-expanded','true');input.closest('.field-shell').classList.add('is-open');});}
['build','browse','available'].forEach(wireLocation);
const today=new Date();const minDate=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;
function formatDate(value){if(!value)return '';return new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'short',year:'numeric'}).format(new Date(`${value}T12:00:00`));}
function dateLabel(key){const s=state[key];const el=document.getElementById(`${key}-date-value`);el.textContent=s.mode==='undecided'?'Not decided yet':s.mode==='range'?(s.start&&s.end?`${formatDate(s.start)} – ${formatDate(s.end)}`:'Select a date range'):(s.start?formatDate(s.start):'Select your date');}
function renderDate(key){const s=state[key];const popup=document.getElementById(`${key}-date-popup`);popup.innerHTML=`<h3>When is your wedding?</h3><div class="date-modes">${[['exact','Exact date'],['range','Date range'],...(key!=='available'?[['undecided','Not decided yet']]:[])].map(([v,l])=>`<label><input type="radio" name="${key}-date-mode" value="${v}" ${s.mode===v?'checked':''}>${l}</label>`).join('')}</div><div class="date-inputs">${s.mode==='undecided'?'<p class="field-value">You can continue without a wedding date.</p>':`<label>${s.mode==='range'?'From':'Wedding date'}<input type="date" name="start" min="${minDate}" value="${s.start}"></label>${s.mode==='range'?`<label>To<input type="date" name="end" min="${s.start||minDate}" value="${s.end}"></label>`:''}`}</div><p class="validation-error" role="alert" hidden></p><div class="popover-footer"><button type="button" class="text-button" data-clear>Clear</button><button type="button" class="small-button" data-done>Done</button></div>`;
 popup.querySelectorAll('input[type=radio]').forEach(r=>r.addEventListener('change',()=>{s.mode=r.value;renderDate(key);dateLabel(key);popup.querySelector(`input[value="${s.mode}"]`).focus();}));
 popup.querySelectorAll('input[type=date]').forEach(input=>input.addEventListener('change',()=>{s[input.name]=input.value;const end=popup.querySelector('[name=end]');if(end)end.min=s.start||minDate;dateLabel(key);}));
 popup.querySelector('[data-clear]').addEventListener('click',()=>{s.start='';s.end='';renderDate(key);dateLabel(key);popup.querySelector('[data-clear]').focus();});
 popup.querySelector('[data-done]').addEventListener('click',()=>{const error=validateDate(key);if(error){popup.querySelector('.validation-error').textContent=error;popup.querySelector('.validation-error').hidden=false;return;}dateLabel(key);closePopups();document.getElementById(`${key}-date-trigger`).focus();});
}
for(const key of ['build','browse','available']){renderDate(key);document.getElementById(`${key}-date-trigger`).addEventListener('click',()=>togglePopup(key,'date'));}
const supplierPopup=document.querySelector('#build-suppliers-popup');supplierPopup.innerHTML=`<h3>Which suppliers do you need?</h3><button type="button" class="text-button" data-select-all>Select all</button><div class="supplier-list">${categories.map(c=>`<label><input type="checkbox" value="${c}">${c}</label>`).join('')}</div><div class="popover-footer"><span class="field-value" id="supplier-count">None selected</span><button type="button" class="small-button" data-done>Done</button></div>`;
function syncSuppliers(){state.build.suppliers=[...supplierPopup.querySelectorAll('input:checked')].map(x=>x.value);const count=state.build.suppliers.length;document.querySelector('#build-suppliers-value').textContent=count===0?'Select suppliers':count===1?state.build.suppliers[0]:count===categories.length?'All suppliers':`${count} suppliers selected`;document.querySelector('#supplier-count').textContent=`${count} selected`;supplierPopup.querySelector('[data-select-all]').textContent=count===categories.length?'Deselect all':'Select all';}
supplierPopup.querySelectorAll('input').forEach(i=>i.addEventListener('change',syncSuppliers));supplierPopup.querySelector('[data-select-all]').addEventListener('click',()=>{const all=state.build.suppliers.length===categories.length;supplierPopup.querySelectorAll('input').forEach(i=>i.checked=!all);syncSuppliers();});supplierPopup.querySelector('[data-done]').addEventListener('click',()=>{closePopups();document.querySelector('#build-suppliers-trigger').focus();});document.querySelector('#build-suppliers-trigger').addEventListener('click',()=>togglePopup('build','suppliers'));
const tabs=[...document.querySelectorAll('[role=tab]')];
const tabMenuToggle=document.querySelector('.tab-menu-toggle');const searchTabs=document.querySelector('#search-tabs');
function closeTabMenu(){searchTabs.classList.remove('is-open');tabMenuToggle.setAttribute('aria-expanded','false');}
function activateTab(tab){closePopups();const hero=document.querySelector('.hero');const expanding=tab.dataset.tab==='browse';if(expanding&&!hero.classList.contains('has-expanded-search')){const gap=Math.max(0,document.querySelector('.hero-copy').getBoundingClientRect().top-document.querySelector('.site-header').getBoundingClientRect().bottom);hero.style.setProperty('--expanded-copy-gap',`${gap}px`);}tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!active;});tabMenuToggle.querySelector('strong').textContent=tab.textContent.trim();closeTabMenu();hero.classList.toggle('has-expanded-search',expanding);if(!expanding)hero.style.removeProperty('--expanded-copy-gap');}
tabMenuToggle.addEventListener('click',()=>{const open=!searchTabs.classList.contains('is-open');searchTabs.classList.toggle('is-open',open);tabMenuToggle.setAttribute('aria-expanded',String(open));});
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>activateTab(tab));tab.addEventListener('keydown',event=>{let i;if(event.key==='ArrowRight')i=(index+1)%tabs.length;else if(event.key==='ArrowLeft')i=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')i=0;else if(event.key==='End')i=tabs.length-1;else return;event.preventDefault();activateTab(tabs[i]);tabs[i].focus();});});
document.addEventListener('click',e=>{if(!e.target.closest('.field'))closePopups();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!categoryModal.hidden){e.preventDefault();closeCategoryModal();return;}const popup=[...document.querySelectorAll('.popover')].find(p=>!p.hidden);if(!popup)return;if(e.key==='Escape'){e.preventDefault();closePopups();document.getElementById(popup.dataset.trigger||popup.id.replace('-popup','-trigger'))?.focus();}if(e.key==='Tab'){const items=[...popup.querySelectorAll('input,button')].filter(el=>!el.disabled);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
function validateDate(key){const s=state[key];if(s.mode==='undecided')return '';if(!s.start)return 'Please choose a wedding date.';if(s.start<minDate)return 'Please choose a future wedding date.';if(s.mode==='range'&&!s.end)return 'Please choose the end of your date range.';if(s.mode==='range'&&s.end<s.start)return 'The end date must be on or after the start date.';return '';}
function clearError(key){document.querySelector(`[data-search="${key}"]>.validation-error`).hidden=true;}
document.querySelectorAll('[data-search]').forEach(form=>{form.addEventListener('input',()=>clearError(form.dataset.search));form.addEventListener('change',()=>clearError(form.dataset.search));form.addEventListener('submit',event=>{event.preventDefault();const key=form.dataset.search;closePopups();const errors=[];const s=state[key];if(key!=='browse'&&!document.getElementById(`${key}-location`).value.trim())errors.push('Enter your wedding location.');const dateError=validateDate(key);if(dateError)errors.push(dateError);if(key==='build'){if(!document.querySelector('#build-budget').value)errors.push('Choose an overall budget, or “Not sure yet”.');if(!s.suppliers.length)errors.push('Select at least one supplier.');}else if(!s.category)errors.push('Select a supplier category.');const error=form.querySelector(':scope > .validation-error');error.textContent=errors.join(' ');error.hidden=!errors.length;if(!errors.length)window.location.assign('https://www.google.com/');});});

const mobileMenuToggle=document.querySelector('.mobile-menu-toggle');const mobileNavigation=document.querySelector('#mobile-navigation');
function closeMobileMenu(){mobileNavigation.hidden=true;mobileMenuToggle.setAttribute('aria-expanded','false');mobileMenuToggle.setAttribute('aria-label','Open navigation');}
mobileMenuToggle.addEventListener('click',()=>{const open=mobileNavigation.hidden;mobileNavigation.hidden=!open;mobileMenuToggle.setAttribute('aria-expanded',String(open));mobileMenuToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
document.addEventListener('click',event=>{if(!event.target.closest('.site-header'))closeMobileMenu();if(!event.target.closest('.search-card'))closeTabMenu();});
document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;if(!mobileNavigation.hidden){closeMobileMenu();mobileMenuToggle.focus();}if(searchTabs.classList.contains('is-open')){closeTabMenu();tabMenuToggle.focus();}});
const mobileMoreToggle=document.querySelector('.mobile-more-toggle');
mobileMoreToggle.addEventListener('click',()=>{const form=mobileMoreToggle.closest('form');const open=!form.classList.contains('mobile-details-open');form.classList.toggle('mobile-details-open',open);mobileMoreToggle.setAttribute('aria-expanded',String(open));mobileMoreToggle.querySelector('.mobile-plus').textContent=open?'−':'+';});

const supplierCarousel=document.querySelector('#supplier-carousel');
const supplierPagination=document.querySelector('.supplier-pagination');
if(supplierCarousel&&supplierPagination){
  const pageCount=5;
  let carouselFrame;
  const pageButtons=Array.from({length:pageCount},(_,index)=>{
    const button=document.createElement('button');
    button.type='button';
    button.setAttribute('aria-label',`Show supplier categories page ${index+1}`);
    button.setAttribute('aria-current',String(index===0));
    button.addEventListener('click',()=>{
      const maxScroll=supplierCarousel.scrollWidth-supplierCarousel.clientWidth;
      supplierCarousel.scrollTo({left:maxScroll*(index/(pageCount-1)),behavior:'smooth'});
    });
    supplierPagination.append(button);
    return button;
  });
  function updateSupplierPagination(){
    const maxScroll=supplierCarousel.scrollWidth-supplierCarousel.clientWidth;
    const active=maxScroll>0?Math.round((supplierCarousel.scrollLeft/maxScroll)*(pageCount-1)):0;
    pageButtons.forEach((button,index)=>button.setAttribute('aria-current',String(index===active)));
  }
  supplierCarousel.addEventListener('scroll',()=>{cancelAnimationFrame(carouselFrame);carouselFrame=requestAnimationFrame(updateSupplierPagination);},{passive:true});
  supplierCarousel.addEventListener('keydown',event=>{
    if(!['ArrowLeft','ArrowRight'].includes(event.key))return;
    event.preventDefault();
    const direction=event.key==='ArrowRight'?1:-1;
    supplierCarousel.scrollBy({left:direction*supplierCarousel.clientWidth*.72,behavior:'smooth'});
  });
  window.addEventListener('resize',updateSupplierPagination,{passive:true});
}
